import unittest
from unittest.mock import patch, MagicMock
import sys
from greet import greet, greet_user, main

class TestGreeting(unittest.TestCase):

    def test_default_greeting(self):
        """Test the default greeting function."""
        self.assertEqual(greet(), "Hello, World!")

    def test_named_greeting(self):
        """Test the greeting for a specific name."""
        self.assertEqual(greet_user("Ada"), "Hello, Ada!")
        self.assertEqual(greet_user("Bob"), "Hello, Bob!")

    @patch('sys.argv', ['greet.py'])
    @patch('sys.stdout', new_callable=MagicMock)
    def test_cli_no_arguments(self, mock_stdout, mock_argv):
        """Test CLI execution with no arguments."""
        main()
        mock_stdout.write.assert_called_with("Hello, World!\n")

    @patch('sys.argv', ['greet.py', 'Ada'])
    @patch('sys.stdout', new_callable=MagicMock)
    def test_cli_with_arguments(self, mock_stdout, mock_argv):
        """Test CLI execution with one argument."""
        main()
        mock_stdout.write.assert_called_with("Hello, Ada!\n")

if __name__ == '__main__':
    unittest.main()
